def _named(labels: list[str]) -> str:
    """["exercise 3"] -> "exercise 3 (paged_write, paged_gather)"; several -> "exercises 3, 6 and 8"."""
    if len(labels) == 1:
        return f"{labels[0]} ({', '.join(_EXERCISES[labels[0]])})"
